+    db.Write(txindex::BlockSeqKey{next_seq + 1}, header_only.GetHash());
+    db.Write(txindex::DBKey{prefix, {next_seq + 1, bucket.front().tx_offset_in_block}}, txindex::EMPTY_VALUE);
+    BOOST_CHECK(LookupTx(txindex, txid) == active_block_hash);
